(()=>{
 const key='bunny-preferences-v1',groups=[['聲音','Sound',[
 ['music','背景音樂','Background music'],['voice','角色配音','Character voices'],['tileSfx','麻雀與立直棒音效','Tiles and riichi sticks'],['uiSfx','按鈕與提示音','Buttons and notifications'],['winSfx','和牌與 CUT-IN 音樂','Win and cut-in sound']]],['動畫','Animation',[
 ['deal','開局動畫','Opening animation'],['handMotion','角色打牌手部動作','Character hand movements'],['calls','吃／碰／槓／立直 Banner','Call and riichi banners'],['winCall','和／自摸 Banner','Ron and tsumo banners'],['eyeCutin','眼部 CUT-IN','Eye cut-ins'],['winCinematic','大牌插圖與特色影片','Big-win art and videos'],['scoreMotion','點數轉移動畫','Score transfer animation']]],['特效','Effects',[
 ['dim','和牌暗場','Win scene dimming'],['flash','閃光與震動','Flashes and shakes'],['doraGlow','寶牌閃亮效果','Dora shine'],['riverGlow','牌河同款牌紫色提示','Matching discard glow']]]];
 const names=groups.flatMap(g=>g[2].map(x=>x[0])),defaults=Object.fromEntries(names.map(n=>[n,true]));let state={...defaults};
 function read(){try{const saved=JSON.parse(localStorage.getItem(key)||'{}');return Object.fromEntries(names.map(n=>[n,typeof saved[n]==='boolean'?saved[n]:true]))}catch{return {...defaults}}}
 function apply(){for(const n of names)document.documentElement.dataset['pref'+n[0].toUpperCase()+n.slice(1)]=String(state[n]);window.dispatchEvent(new Event('bunny:prefs'));window.dispatchEvent(new Event('bunny:graphics'))}
 function set(next){for(const n of names)if(typeof next[n]==='boolean')state[n]=next[n];try{localStorage.setItem(key,JSON.stringify(state))}catch{}apply()}
 let dialog;const english=()=>document.documentElement.dataset.language==='en'||localStorage.getItem('bunny-language')==='en';
 function render(){const en=english(),lang=en?'en':'zh';dialog.innerHTML='<form method="dialog"><div class="prefs-title"><h2>'+(en?'Game settings':'遊戲設定')+'</h2><button aria-label="'+(en?'Close':'關閉')+'">×</button></div><label class="prefs-language">'+(en?'Language':'語言')+'<select aria-label="Language"><option value="zh">繁體中文</option><option value="en">English</option></select></label><p>'+(en?'Tick to enable. Your choices are saved on this device.':'勾選即啟用，設定會保存在此裝置。')+'</p>'+groups.map(g=>'<fieldset><legend>'+g[en?1:0]+'</legend>'+g[2].map(([n,zh,enLabel])=>'<label><input type="checkbox" data-pref="'+n+'" '+(state[n]?'checked':'')+'><span>'+(en?enLabel:zh)+'</span></label>').join('')+'</fieldset>').join('')+'<button class="prefs-done">'+(en?'Done':'完成')+'</button></form>';dialog.querySelector('select').value=lang;dialog.querySelector('select').onchange=e=>{try{localStorage.setItem('bunny-language',e.target.value)}catch{}window.dispatchEvent(new CustomEvent('bunny:set-language',{detail:e.target.value}));document.documentElement.dataset.language=e.target.value;render()};dialog.querySelectorAll('[data-pref]').forEach(input=>input.onchange=()=>set({[input.dataset.pref]:input.checked}))}
 function open(){if(!dialog){dialog=document.createElement('dialog');dialog.className='bunny-prefs';dialog.dataset.languageSwitch='true';document.body.append(dialog);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})}render();window.BunnyAudio?.unlock();dialog.showModal()}
 state=read();window.BunnyPrefs={enabled:n=>state[n]!==false,read:()=>({...state}),set,open,close:()=>dialog?.close()};apply();window.addEventListener('storage',e=>{if(e.key===key){state=read();apply();if(dialog?.open)render()}});
 const style=document.createElement('style');style.textContent=`.bunny-prefs{box-sizing:border-box;width:min(520px,calc(100vw - 28px));max-height:88dvh;padding:22px;color:#ffefd5;background:#211722;border:1px solid #c49a68;border-radius:14px;font:16px/1.5 system-ui;z-index:99999}.bunny-prefs::backdrop{background:#000b}.bunny-prefs *{box-sizing:border-box}.prefs-title{display:flex;align-items:center;justify-content:space-between;gap:16px}.prefs-title h2{margin:0;font-size:24px}.bunny-prefs button{background:#e5c58e;color:#25182a;border:1px solid #ffe7bd;border-radius:6px;min-height:44px;padding:8px 18px;font:600 16px system-ui;cursor:pointer}.bunny-prefs p{font-size:13px;color:#d8c1ac}.bunny-prefs fieldset{border:1px solid #84634e;border-radius:8px;margin:18px 0;padding:10px 14px}.bunny-prefs legend{color:#e7c386;padding:0 8px}.bunny-prefs label{display:flex;align-items:center;gap:13px;min-height:44px;text-align:left}.bunny-prefs input{width:21px;height:21px;accent-color:#ce9f5b;flex-shrink:0}.bunny-prefs span{overflow-wrap:anywhere}.prefs-language{justify-content:space-between;margin-top:14px}.prefs-language select{font-size:16px;padding:8px;color:#ffefd5;background:#352638;border:1px solid #a98968;border-radius:5px}.prefs-done{width:100%}html[data-pref-deal=false] .arena *,html[data-pref-deal=false] #startup-curtain{animation:none!important;transition:none!important}html[data-pref-dim=false] .mangan-art-dim{opacity:0!important}html[data-pref-flash=false] .mangan-art-hit,html[data-pref-flash=false] .win-impact-flash{display:none!important}html[data-pref-flash=false] .mangan-art-screen{animation:none!important}`;document.head.append(style);
})();
